          .admin-dashboard-terminal-bar > div:first-child { min-width: 0; max-width: 100%; }
          .admin-dashboard-terminal-label { min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
